arguments.command:
python - <<'EOF'
from pptx import Presentation
from pptx.util import Emu
p = Presentation('Q4_financial_report.pptx')
print("Slide size:", p.slide_width, p.slide_height)
for i, s in enumerate(p.slides):
    print(f"\n=== SLIDE {i} (layout: {s.slide_layout.name}) ===")
    for sh in s.shapes:
        ph = ""
        try:
            if sh.is_placeholder:
                ph = f"ph={sh.placeholder_format.type} idx={sh.placeholder_format.idx}"
        except Exception:
            pass
        txt = ""
        if sh.has_text_frame:
            txt = " | ".join(r.text for para in sh.text_frame.paragraphs for r in para.runs)[:90]
        print(f"  shape id={sh.shape_id} name={sh.name!r} {ph} L={Emu(sh.left).inches:.2f} T={Emu(sh.top).inches:.2f} W={Emu(sh.width).inches:.2f} H={Emu(sh.height).inches:.2f} :: {txt}")
EOF
